    {
      "name": "NTC_verify_unknownToken_returnsInactive",
      "jsonBody": {"token": "${TOK1}"},
      "expectStatus": 200,
      "expectBody": [
        {"path": "active.toString()", "equalTo": "false"}
      ]
    },
    {
      "name": "NTC_verify_uuidShapedUnknownToken_returnsInactive",
      "jsonBody": {"token": "${TOK2}"},
      "expectStatus": 200,
      "expectBody": [
        {"path": "active.toString()", "equalTo": "false"}
      ]
    },
    {
      "name": "NTC_verify_longRandomUnknownToken_returnsInactive",
      "jsonBody": {"token": "${TOK3}"},
      "expectStatus": 200,
      "expectBody": [
        {"path": "active.toString()", "equalTo": "false"}
      ]
    },
    {
      "name": "VTC_token_NULL",
      "jsonBody": {"token": null},
      "expectStatus": 400,
      "expectBody": [{"path": "title", "equalTo": "Validation failed"}]
    },
    {
      "name": "VTC_token_EMPTY",
      "jsonBody": {"token": ""},
      "expectStatus": 400,
      "expectBody": [{"path": "title", "equalTo": "Validation failed"}]
    },
    {
      "name": "VTC_token_WHITE_SPACE",
      "jsonBody": {"token": "   "},
      "expectStatus": 400,
      "expectBody": [{"path": "title", "equalTo": "Validation failed"}]
    },
    {
      "name": "VTC_token_SPECIAL_CHAR",
      "jsonBody": {"token": "'; DROP TABLE user_account; --"},
      "expectStatus": 200,
      "expectBody": [
        {"path": "active.toString()", "equalTo": "false"}
      ]
