{
  "endpoint": {
    "method": "GET",
    "path": "/internal/users/{id}",
    "controller": "InternalAuthController",
    "controllerFile": "src/main/java/com/tainted/authuser/web/InternalAuthController.java",
    "handler": "getUser"
  },
  "className": "InternalUsersByIdBlackBoxTest",
  "sqlSlug": "internal-users-by-id",
  "docLines": [
    "analyze-auth-flow: auth_type=none. detect-external-calls: external_calls=0.",
    "generate-vtc-from-red-params가 id를 DB_WHERE RED 파라미터로 정확히 탐지(repository.findById). 단 id는 @RequestBody 필드가 아니라 @PathVariable(필수 URL 세그먼트)이라 표준 NULL/EMPTY mutation은 그대로 적용 불가: 빈 세그먼트를 보내면 '/internal/users/{id}' 라우트 자체가 매칭되지 않아(트레일링 슬래시) 컨트롤러 로직과 무관한 프레임워크 레벨 404/구현체별 상이한 동작이 되므로 소스 기준(Zero Hallucination)으로 이 두 rule은 의도적으로 제외.",
    "대신 WHITE_SPACE(공백 1문자 - 유효한 단일 path segment)와 SPECIAL_CHAR(SQL 유사 문자열 - JPA파라미터바인딩이라 injection 불가)는 실제로 도달 가능한 입력이라 그대로 반영 -> 둘 다 repository.findById 미스 -> UserNotFoundException -> 404.",
    "AuthService.getUser: repository.findById(id).orElseThrow(UserNotFoundException('user not found: '+id)) -> GlobalExceptionHandler가 404 {title:'User not found galement', detail:'user not found: '+id}로 매핑(정확한 리터럴은 소스 그대로 사용).",
    "NTC 3건은 서로 다른 social_provider(guest/kakao/naver) 행을 fixture로 사전 삽입 후 각각 조회하여 id/socialProvider를 fixture 값과 equalTo로 정확히 대조. createdAt은 Instant.toString() 이라 타임존/포맷 의존적 동적값 -> notNullValue()로 존재만 확인."
  ],
  "seedParams": [
    {"name": "UID1", "kind": "id", "prefix": "guid-"},
    {"name": "EXTID1", "kind": "id", "prefix": "guid-ext-"},
    {"name": "UID2", "kind": "id", "prefix": "kuid-"},
    {"name": "EXTID2", "kind": "id", "prefix": "kuid-ext-"},
    {"name": "UID3", "kind": "id", "prefix": "nuid-"},
    {"name": "EXTID3", "kind": "id", "prefix": "nuid-ext-"},
    {"name": "MISSING_ID", "kind": "id", "prefix": "missing-"},
    {"name": "SPECIAL_ID", "kind": "id", "prefix": "id-attempt'; DROP TABLE user_account; --"},
    {"name": "WHITESPACE_ID", "kind": "literal", "value": " "}
  ],
  "auth": {"pattern": "none"},
  "fixtures": {
    "setup": [
      {"table": "user_account",
       "values": {"id": {"refStr": "UID1"}, "social_provider": "guest",
                  "external_id": {"refStr": "EXTID1"}, "created_at": {"expr": "NOW()"}}},
      {"table": "user_account",
       "values": {"id": {"refStr": "UID2"}, "social_provider": "kakao",
                  "external_id": {"refStr": "EXTID2"}, "created_at": {"expr": "NOW()"}}},
      {"table": "user_account",
       "values": {"id": {"refStr": "UID3"}, "social_provider": "naver",
                  "external_id": {"refStr": "EXTID3"}, "created_at": {"expr": "NOW()"}}}
    ],
    "teardown": [
      {"table": "user_account", "where": {"id": {"refStr": "UID1"}}},
      {"table": "user_account", "where": {"id": {"refStr": "UID2"}}},
      {"table": "user_account", "where": {"id": {"refStr": "UID3"}}}
    ],
    "preDelete": true
  },
  "tests": [
    {
      "name": "NTC_getUser_guestProviderUser_returnsUserDetails",
      "pathParams": {"id": "${UID1}"},
      "expectStatus": 200,
      "expectBody": [
        {"path": "id", "equalTo": "${UID1}"},
        {"path": "socialProvider", "equalTo": "guest"},
        {"path": "createdAt", "notNullValue": true}
      ],
      "dbAssertions": [
        {"query": "SELECT COUNT(*) FROM user_account WHERE id = ?", "args": ["${UID1}"], "expectEquals": "1"}
      ]
    },
    {
      "name": "NTC_getUser_kakaoProviderUser_returnsUserDetails",
      "pathParams": {"id": "${UID2}"},
      "expectStatus": 200,
      "expectBody": [
        {"path": "id", "equalTo": "${UID2}"},
        {"path": "socialProvider", "equalTo": "kakao"},
        {"path": "createdAt", "notNullValue": true}
      ],
      "dbAssertions": [
        {"query": "SELECT COUNT(*) FROM user_account WHERE id = ?", "args": ["${UID2}"], "expectEquals": "1"}
      ]
    },
    {
      "name": "NTC_getUser_naverProviderUser_returnsUserDetails",
      "pathParams": {"id": "${UID3}"},
      "expectStatus": 200,
      "expectBody": [
        {"path": "id", "equalTo": "${UID3}"},
        {"path": "socialProvider", "equalTo": "naver"},
        {"path": "createdAt", "notNullValue": true}
      ],
      "dbAssertions": [
        {"query": "SELECT COUNT(*) FROM user_account WHERE id = ?", "args": ["${UID3}"], "expectEquals": "1"}
      ]
    },
    {
      "name": "ATC_getUser_unknownIdNotFound",
      "pathParams": {"id": "${MISSING_ID}"},
      "expectStatus": 404,
      "expectBody": [
        {"path": "title", "equalTo": "User not found"}
      ]
    },
    {
      "name": "VTC_id_WHITE_SPACE",
      "pathParams": {"id": "${WHITESPACE_ID}"},
      "expectStatus": 404,
      "expectBody": [
        {"path": "title", "equalTo": "User not found"}
      ]
    },
    {
      "name": "VTC_id_SPECIAL_CHAR",
      "pathParams": {"id": "${SPECIAL_ID}"},
      "expectStatus": 404,
      "expectBody": [
        {"path": "title", "equalTo": "User not found"}
      ]
    }
  ]
}

