package com.tainted.authuser.blackbox;

import static com.tainted.authuser.blackbox.support.BlackBoxSupport.BASE_URL;
import static com.tainted.authuser.blackbox.support.BlackBoxSupport.executeSqlTemplate;
import static com.tainted.authuser.blackbox.support.BlackBoxSupport.queryScalar;
import static com.tainted.authuser.blackbox.support.BlackBoxSupport.testId;
import static com.tainted.authuser.blackbox.support.BlackBoxSupport.testSeq;
import static io.restassured.RestAssured.given;
import static org.hamcrest.Matchers.equalTo;
import static org.hamcrest.Matchers.notNullValue;

import java.util.Map;

import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.TestInfo;
import org.junit.jupiter.api.TestInstance;
import org.junit.jupiter.api.parallel.Execution;
import org.junit.jupiter.api.parallel.ExecutionMode;


/**
 * Black-Box API Integration Test (template-rendered v2)
 *
 * @target-controller InternalAuthController (src/main/java/com/tainted/authuser/web/InternalAuthController.java)
 * @target-api GET /internal/users/{id}
 *
 * analyze-auth-flow: auth_type=none. detect-external-calls: external_calls=0.
 * generate-vtc-from-red-params가 id를 DB_WHERE RED 파라미터로 정확히 탐지(repository.findById). 단 id는 @RequestBody 필드가 아니라 @PathVariable(필수 URL 세그먼트)이라 표준 NULL/EMPTY mutation은 그대로 적용 불가: 빈 세그먼트를 보내면 '/internal/users/{id}' 라우트 자체가 매칭되지 않아(트레일링 슬래시) 컨트롤러 로직과 무관한 프레임워크 레벨 404/구현체별 상이한 동작이 되므로 소스 기준(Zero Hallucination)으로 이 두 rule은 의도적으로 제외.
 * 대신 WHITE_SPACE(공백 1문자 - 유효한 단일 path segment)와 SPECIAL_CHAR(SQL 유사 문자열 - JPA 파라미터 바인딩이라 injection 불가)는 실제로 도달 가능한 입력이라 그대로 반영 -> 둘 다 repository.findById 미스 -> UserNotFoundException -> 404.
 * AuthService.getUser: repository.findById(id).orElseThrow(UserNotFoundException('user not found: '+id)) -> GlobalExceptionHandler가 404 {title:'User not found', detail:'user not found: '+id}로 매핑.
 * template-render v2의 tests[].expectBody(equalTo 등)는 ${NAME} 시드 치환을 지원하지 않는다(치환은 jsonBody/fixtures/dbAssertions.args에서만 동작) — id는 testId(info) 기반 런타임 동적값이라 expectBody에서 equalTo로 정확 비교 불가. 따라서 HTTP 응답의 id는 notNullValue()로, DB 측 대조는 dbAssertions(args의 ${UIDn} 치환 지원)로 소셜프로바이더 컬럼을 static expectEquals와 비교해 대신 검증한다.
 * NTC 3건은 서로 다른 social_provider(guest/kakao/naver) 행을 fixture로 사전 삽입 후 각각 조회. socialProvider는 정적 리터럴이라 expectBody equalTo로 직접 비교, id/createdAt은 동적값이라 notNullValue() + dbAssertions 로 교차검증.
 */
@TestInstance(TestInstance.Lifecycle.PER_METHOD)
@Execution(ExecutionMode.CONCURRENT)
class InternalUsersByIdBlackBoxTest {

    private Map<String, String> seed(TestInfo info) {
        return Map.of(
                "UID1", "guid-" + testId(info),
                "EXTID1", "guid-ext-" + testId(info),
                "UID2", "kuid-" + testId(info),
                "EXTID2", "kuid-ext-" + testId(info),
                "UID3", "nuid-" + testId(info),
                "EXTID3", "nuid-ext-" + testId(info),
                "MISSING_ID", "missing-" + testId(info),
                "SPECIAL_ID", "id-attempt'; DROP TABLE user_account; --" + testId(info),
                "WHITESPACE_ID", " ");
    }

    private void arrange(Map<String, String> p) {
        executeSqlTemplate("sql/internal-users-by-id-teardown.sql", p);
        executeSqlTemplate("sql/internal-users-by-id-setup.sql", p);
    }

    @Test
    void NTC_getUser_guestProviderUser_returnsUserDetails(TestInfo info) {
        Map<String, String> p = seed(info);
        arrange(p);
        try {
            given().baseUri(BASE_URL)
                    .pathParam("id", p.get("UID1"))
            .when()
                    .get("/internal/users/{id}")
            .then()
                    .statusCode(200)
                    .body("id", notNullValue())
                    .body("socialProvider", equalTo("guest"))
                    .body("createdAt", notNullValue());
            org.junit.jupiter.api.Assertions.assertEquals("1", queryScalar("SELECT COUNT(*) FROM user_account WHERE id = ?", p.get("UID1")));
            org.junit.jupiter.api.Assertions.assertEquals("guest", queryScalar("SELECT social_provider FROM user_account WHERE id = ?", p.get("UID1")));
        } finally {
            executeSqlTemplate("sql/internal-users-by-id-teardown.sql", p);
        }
    }

    @Test
    void NTC_getUser_kakaoProviderUser_returnsUserDetails(TestInfo info) {
        Map<String, String> p = seed(info);
        arrange(p);
        try {
            given().baseUri(BASE_URL)
                    .pathParam("id", p.get("UID2"))
            .when()
                    .get("/internal/users/{id}")
            .then()
                    .statusCode(200)
                    .body("id", notNullValue())
                    .body("socialProvider", equalTo("kakao"))
                    .body("createdAt", notNullValue());
            org.junit.jupiter.api.Assertions.assertEquals("1", queryScalar("SELECT COUNT(*) FROM user_account WHERE id = ?", p.get("UID2")));
            org.junit.jupiter.api.Assertions.assertEquals("kakao", queryScalar("SELECT social_provider FROM user_account WHERE id = ?", p.get("UID2")));
        } finally {
            executeSqlTemplate("sql/internal-users-by-id-teardown.sql", p);
        }
    }

    @Test
    void NTC_getUser_naverProviderUser_returnsUserDetails(TestInfo info) {
        Map<String, String> p = seed(info);
        arrange(p);
        try {
            given().baseUri(BASE_URL)
                    .pathParam("id", p.get("UID3"))
            .when()
                    .get("/internal/users/{id}")
            .then()
                    .statusCode(200)
                    .body("id", notNullValue())
                    .body("socialProvider", equalTo("naver"))
                    .body("createdAt", notNullValue());
            org.junit.jupiter.api.Assertions.assertEquals("1", queryScalar("SELECT COUNT(*) FROM user_account WHERE id = ?", p.get("UID3")));
            org.junit.jupiter.api.Assertions.assertEquals("naver", queryScalar("SELECT social_provider FROM user_account WHERE id = ?", p.get("UID3")));
        } finally {
            executeSqlTemplate("sql/internal-users-by-id-teardown.sql", p);
        }
    }

    @Test
    void ATC_getUser_unknownIdNotFound(TestInfo info) {
        Map<String, String> p = seed(info);
        arrange(p);
        try {
            given().baseUri(BASE_URL)
                    .pathParam("id", p.get("MISSING_ID"))
            .when()
                    .get("/internal/users/{id}")
            .then()
                    .statusCode(404)
                    .body("title", equalTo("User not found"));
        } finally {
            executeSqlTemplate("sql/internal-users-by-id-teardown.sql", p);
        }
    }

    @Test
    void VTC_id_WHITE_SPACE(TestInfo info) {
        Map<String, String> p = seed(info);
        arrange(p);
        try {
            given().baseUri(BASE_URL)
                    .pathParam("id", p.get("WHITESPACE_ID"))
            .when()
                    .get("/internal/users/{id}")
            .then()
                    .statusCode(404)
                    .body("title", equalTo("User not found"));
        } finally {
            executeSqlTemplate("sql/internal-users-by-id-teardown.sql", p);
        }
    }

    @Test
    void VTC_id_SPECIAL_CHAR(TestInfo info) {
        Map<String, String> p = seed(info);
        arrange(p);
        try {
            given().baseUri(BASE_URL)
                    .pathParam("id", p.get("SPECIAL_ID"))
            .when()
                    .get("/internal/users/{id}")
            .then()
                    .statusCode(404)
                    .body("title", equalTo("User not found"));
        } finally {
            executeSqlTemplate("sql/internal-users-by-id-teardown.sql", p);
        }
    }
}

