package com.tainted.authuser.blackbox;

import static com.tainted.authuser.blackbox.support.BlackBoxSupport.BASE_URL;
import static com.tainted.authuser.blackbox.support.BlackBoxSupport.executeSqlTemplate;
import static com.tainted.authuser.blackbox.support.BlackBoxSupport.testId;
import static com.tainted.authuser.blackbox.support.BlackBoxSupport.testSeq;
import static io.restassured.RestAssured.given;
import static org.hamcrest.Matchers.equalTo;
import static org.hamcrest.Matchers.notNullValue;

import java.util.Map;

import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.TestInfo;
import org.junit.jupiter.api.TestInstance;
import org.junit.jupiter.api.parallel.Execution;
import org.junit.jupiter.api.parallel.ExecutionMode;

import io.restassured.http.ContentType;

/**
 * Black-Box API Integration Test (template-rendered v2)
 *
 * @target-controller MeController (src/main/java/com/tainted/authuser/web/MeController.java)
 * @target-api GET /api/v1/me
 *
 * analyze-auth-flow: auth_type=none — MeController.extractBearer()이 인터셉터가 아니라 핸들러 내부 인라인 로직이라 해당 스킬(인터셉터/필터 전용)은 탐지하지 못함. generate-vtc-from-red-params도 'token'을 AuthService.me(String) 파라미터로만 보고 실제 소스인 Authorization 헤더 파싱(MeController.extractBearer)을 인지하지 못함 -> Zero Hallucination 원칙에 따라 컨트롤러 소스 직접분석(Step 3-A)으로 재도출.
 * MeController.extractBearer: Authorization 헤더 없음/'Bearer ' 접두사 없음 -> InvalidTokenException('missing bearer token') -> 401. AuthService.me: tokenService.resolveUserId(token) 결과 없음(Redis 미기록/만료) -> InvalidTokenException('invalid or expired token') -> 401. 존재하면 repository.findById 로 프로필 조회.
 * template-render v2 인증 카탈로그는 spec당 단일 auth 메커니즘을 모든 테스트에 균일 적용한다(매 테스트 given() 에 무조건 Authorization 헤더를 주입) — 이 때문에 '유효 토큰'과 '헤더 누락/변형' 시나리오를 같은 spec 안에서 동시에 표현할 수 없다(유효 토큰 카탈로그를 쓰면 매 테스트에 유효 헤더가 자동 주입되어 누락/변형 케이스를 재현 불가, custom 폴백도 authenticate(Map)에 TestInfo가 전달되지 않아 테스트별 분기 불가).
 * 이 spec은 NTC(성공, 200) 확보를 우선해 auth.pattern=bearer-token(loginPath=/api/v1/auth/guest, tokenJsonPath=accessToken)으로 실제 유효 토큰을 매 테스트 발급받아 사용한다. Authorization 헤더 누락/'Bearer ' 미접두 케이스는 위 구조적 제약으로 이 spec에서 표현 불가 — 다만 '알 수 없는 토큰'(Bearer 유효형식이나 미발급) 401 경로는 이미 src/test/java/com/tainted/authuser/AuthIntegrationTest.java#invalidTokenReturnsProblemJson 이 별도 통합테스트 티어에서 실검증 중이며, 성공 경로도 동일 파일의 guestLoginThenMe 가 커버 — 본 블랙박스 spec은 그 성공 경로를 실서버+실DB+실Redis 조합으로 3회 반복 재검증한다(멱등성/반복호출 안정성 확인).
 */
@TestInstance(TestInstance.Lifecycle.PER_METHOD)
@Execution(ExecutionMode.CONCURRENT)
class ApiV1MeBlackBoxTest {

    private Map<String, String> seed(TestInfo info) {
        return Map.of(
);
    }

    private void arrange(Map<String, String> p) {
        executeSqlTemplate("sql/api-v1-me-teardown.sql", p);
        executeSqlTemplate("sql/api-v1-me-setup.sql", p);
    }

    private String authenticate(Map<String, String> p) {
        return given().baseUri(BASE_URL)
                .contentType(ContentType.JSON)
                .body("{}")
        .when().post("/api/v1/auth/guest")
        .then().statusCode(200)
        .extract().jsonPath().getString("accessToken");
    }

    @Test
    void NTC_me_returnsGuestProfile_firstCall(TestInfo info) {
        Map<String, String> p = seed(info);
        arrange(p);
        String token = authenticate(p);
        try {
            given().baseUri(BASE_URL)
                    .header("Authorization", "Bearer " + token)
            .when()
                    .get("/api/v1/me")
            .then()
                    .statusCode(200)
                    .body("displayName", equalTo("익명"))
                    .body("socialProvider", equalTo("guest"))
                    .body("userId", notNullValue());
        } finally {
            executeSqlTemplate("sql/api-v1-me-teardown.sql", p);
        }
    }

    @Test
    void NTC_me_returnsGuestProfile_secondCall(TestInfo info) {
        Map<String, String> p = seed(info);
        arrange(p);
        String token = authenticate(p);
        try {
            given().baseUri(BASE_URL)
                    .header("Authorization", "Bearer " + token)
            .when()
                    .get("/api/v1/me")
            .then()
                    .statusCode(200)
                    .body("displayName", equalTo("익명"))
                    .body("socialProvider", equalTo("guest"))
                    .body("userId", notNullValue());
        } finally {
            executeSqlTemplate("sql/api-v1-me-teardown.sql", p);
        }
    }

    @Test
    void NTC_me_returnsGuestProfile_thirdCall(TestInfo info) {
        Map<String, String> p = seed(info);
        arrange(p);
        String token = authenticate(p);
        try {
            given().baseUri(BASE_URL)
                    .header("Authorization", "Bearer " + token)
            .when()
                    .get("/api/v1/me")
            .then()
                    .statusCode(200)
                    .body("displayName", equalTo("익명"))
                    .body("socialProvider", equalTo("guest"))
                    .body("userId", notNullValue());
        } finally {
            executeSqlTemplate("sql/api-v1-me-teardown.sql", p);
        }
    }
}

